contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, address protocolFeeDest) public payable {
        bool initialized;
        bool reverted;
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config;

        try c.getRoyalties(tokenId) returns (ICreatorRoyaltiesControl.RoyaltyConfiguration memory cfg) {
            initialized = true;
            config = cfg;
        } catch {
            initialized = false;
        }

        assert(
            (!initialized && !_hasRoyaltyRecipient()) ||
            (initialized && config.royaltyBPS <= 10000)
        );
    }

    function _hasRoyaltyRecipient() internal view returns (bool) {
        bool ok;
        address recipient;
        try c.getRoyalties(0) returns (ICreatorRoyaltiesControl.RoyaltyConfiguration memory cfg) {
            ok = true;
            recipient = cfg.royaltyRecipient;
        } catch {
            ok = false;
        }
        return ok && recipient != address(0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId, uint256 salePrice) public payable {
        require(salePrice <= type(uint256).max / 10000, "salePrice too large");

        ICreatorRoyaltiesControl.RoyaltyConfiguration memory cfg = c.getRoyalties(tokenId);
        uint32 bps = cfg.royaltyBPS;
        address expectedReceiver = cfg.royaltyRecipient;

        (address actualReceiver, uint256 actualAmount) = c.royaltyInfo(tokenId, salePrice);

        assert(actualReceiver == expectedReceiver);
        assert(actualAmount == (uint256(bps) * salePrice) / 10000);
    }

    receive() external payable {}
}

